SELECT /*+ MAX_EXECUTION_TIME(5000) */ x.strategy_id, x.status AS rel_status, r.rule_id, CASE WHEN r.rule_name LIKE '%countryCode%' OR r.rule_name LIKE '%区号%' OR r.rule_name LIKE '%Province%' OR r.rule_name LIKE '%次数%' THEN r.rule_name ELSE CONCAT('len=', CHAR_LENGTH(r.rule_name)) END AS rule_name_g, r.status AS rule_status, r.feature_type, r.feature_id, r.condition_type, CASE WHEN r.rule_name LIKE '%countryCode%' OR r.rule_name LIKE '%区号%' OR r.rule_name LIKE '%Province%' OR r.rule_name LIKE '%次数%' THEN r.condition_value ELSE CONCAT('len=', CHAR_LENGTH(r.condition_value)) END AS right_value, CHAR_LENGTH(r.condition_value) AS right_len, r.create_time, r.update_time FROM luckyus_iriskcontrolservice.t_rms_engine_strategy_relation x JOIN luckyus_iriskcontrolservice.t_rms_engine_rule r ON r.rule_id = x.rule_id WHERE x.strategy_id LIKE 'strategy_eoHQ6Qs_FRqp'
